import java.util.*;

class Solution {
    public String oddString(String[] words) {
        int[] first = diff(words[0]);
        int[] second = diff(words[1]);
        int[] common = Arrays.equals(first, second) ? first : diff(words[2]);

        for (String word : words) {
            if (!Arrays.equals(diff(word), common)) {
                return word;
            }
        }
        return "";
    }

    private int[] diff(String word) {
        int[] answer = new int[word.length() - 1];
        for (int i = 1; i < word.length(); i++) {
            answer[i - 1] = word.charAt(i) - word.charAt(i - 1);
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public String oddString(String[] words) {
        Map<String, Integer> count = new HashMap<>();
        Map<String, String> representative = new HashMap<>();

        for (String word : words) {
            String key = key(word);
            count.put(key, count.getOrDefault(key, 0) + 1);
            representative.put(key, word);
        }

        for (Map.Entry<String, Integer> entry : count.entrySet()) {
            if (entry.getValue() == 1) {
                return representative.get(entry.getKey());
            }
        }
        return "";
    }

    private String key(String word) {
        StringBuilder builder = new StringBuilder();
        for (int i = 1; i < word.length(); i++) {
            builder.append(word.charAt(i) - word.charAt(i - 1)).append('#');
        }
        return builder.toString();
    }
}

class Solution {
    public String oddString(String[] words) {
        boolean firstMatchesSecond = samePattern(words[0], words[1]);
        boolean firstMatchesThird = samePattern(words[0], words[2]);
        if (!firstMatchesSecond && !firstMatchesThird) {
            return words[0];
        }

        String common = words[0];
        for (String word : words) {
            if (!samePattern(word, common)) {
                return word;
            }
        }
        return "";
    }

    private boolean samePattern(String a, String b) {
        for (int i = 1; i < a.length(); i++) {
            if (a.charAt(i) - a.charAt(i - 1) != b.charAt(i) - b.charAt(i - 1)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public String oddString(String[] words) {
        String[] ordered = words.clone();
        Arrays.sort(ordered, Comparator.comparing(this::key));

        if (key(ordered[0]).equals(key(ordered[1]))) {
            return ordered[ordered.length - 1];
        }
        return ordered[0];
    }

    private String key(String word) {
        StringBuilder builder = new StringBuilder();
        for (int i = 1; i < word.length(); i++) {
            builder.append(word.charAt(i) - word.charAt(i - 1)).append('#');
        }
        return builder.toString();
    }
}
